def simple_toml_load(path):
    # Minimal TOML parser for .clog.toml: only need [clog] section with repository, from-latest-tag, changelog, etc.
    # And also handle simple key = "value" and key = true/false
    data = {}
    current_section = None
    try:
        with open(path, "r") as f:
            content = f.read()
            if content.strip() == "":
