                key, val = line.split("=",1)
                key=key.strip()
                val=val.strip()
                # Remove quotes
                if val.startswith('"') and val.endswith('"'):
                    val=val[1:-1]
                elif val.startswith("'") and val.endswith("'"):
                    val=val[1:-1]
                elif val.lower() == "true":
                    val=True
                elif val.lower() == "false":
                    val=False
                else:
                    # try to keep as string
                    pass
                if current_section:
                    data[current_section][key]=val
                else:
                    data[key]=val
            return data
    except FileNotFoundError:
        raise
    except SystemExit:
        raise
    except Exception as e:
        # If it's a parse error we already handled
        if "Failed to parse" in str(e):
            raise
        toml_parse_error()
    return data

