    md_lines = [anchor_line, header_line, ""]
    order = ["Breaking Changes", "Features", "Bug Fixes", "Performance Improvements", "Documentation", "Styles", "Refactoring", "Tests", "Chores", "Build", "Continuous Integration", "Reverts"]
    for sec in order:
