        patch_json = "true" if is_patch else "false"
        if not sections:
            sections_json = "null"
        else:
            sec_parts = []
            for sec in order:
                if sec in sections:
                    commits_list = sections[sec]
                    commit_strs = []
                    for c in commits_list:
                        comp = "null" if c["component"] is None else f'"{c["component"]}"'
                        subj_json = json.dumps(c["subject"])
