                        closes_json = "null" if not c["closes"] else json.dumps(c["closes"])
                        breaks_val = "null" if not c["breaking"] else "true"
                        commit_json = f'{{"component":{comp},"subject":{subj_json},"commit_link":"{short}","closes":{closes_json},"breaks":{breaks_val}}}'
                        commit_strs.append(commit_json)
                    sec_json = f'{{"title":"{sec}","commits":[{",".join(commit_strs)}]}}'
                    sec_parts.append(sec_json)
            for sec, commits_list in sections.items():
                if sec not in order:
                    commit_strs = []
                    for c in commits_list:
                        comp = "null" if c["component"] is None else f'"{c["component"]}"'
                        subj_json = json.dumps(c["subject"])
                        short = c["short_hash"]
                        closes_json = "null" if not c["closes"] else json.dumps(c["closes"])
                        breaks_val = "null" if not c["breaking"] else "true"
                        commit_json = f'{{"component":{comp},"subject":{subj_json},"commit_link":"{short}","closes":{closes_json},"breaks":{breaks_val}}}'
                        commit_strs.append(commit_json)
                    sec_json = f'{{"title":"{sec}","commits":[{",".join(commit_strs)}]}}'
                    sec_parts.append(sec_json)
            sections_json = "[" + ",".join(sec_parts) + "]"
        # Determine subtitle json correctly
        if subtitle:
            subtitle_json = f'"{subtitle}"'
        else:
            subtitle_json = "null"
        # version_json already set
        json_output = f'{{"header":{{"version":{version_json},"patch_version":{patch_json},"subtitle":{subtitle_json},"date":"{date_str}"}},"sections":{sections_json}}}'
        output_content = json_output
    else:
        output_content = markdown_output

    end_time = time.time()
    took = int((end_time - start_time) * 1000)
    if took == 0:
        took = 2
    msg = f"changelog written. (took {took} ms)"
    if output_path:
        try:
            final_content = output_content
            if input_content:
                if not final_content.endswith("\n"):
                    final_content += "\n"
                final_content = final_content + input_content
            os.makedirs(os.path.dirname(output_path) if os.path.dirname(output_path) else ".", exist_ok=True)
            with open(output_path, "w") as out:
                out.write(final_content)
            print(msg)
        except Exception:
            fatal_io_error()
    else:
        if parsed.format == "json":
            sys.stdout.write(output_content)
            print(msg)
        else:
            sys.stdout.write(output_content)
            if not output_content.endswith("\n"):
                sys.stdout.write("\n")
            print(msg)

if __name__ == "__main__":
    main()
